uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float spark_rate : 0.0 .. 10.0 = 2.0;
uniform float glow : 0.0 .. 1.0 = 0.4;
state fixed ph;
state fixed sparks[8];
state int next_spark;
state float last_tap;
void update() {
  ph = fract(ph + fixed(dt * speed * 0.5));
  if (imu_tap > last_tap) {
    last_tap = imu_tap;
    sparks[next_spark & 7] = fixed(hash(float(frame)));
    next_spark = next_spark + 1;
  }
  if (frame % 30 == 0) {
    int i = int(hash(float(frame)) * fixed(8.0));
    sparks[i] = fixed(hash(float(frame) * 3.0));
  }
}
vec3 shade(Led led) {
  fixed h = fixed(hash(fixed(led.idx) * fixed(0.314)));
  fixed base = sin(fixed(led.s) * fixed(12.0) + ph);
  fixed emb = clamp(base * fixed(2.0) + fixed(glow), fixed(0.0), fixed(1.0));
  vec3 c = hsv2rgb(fixed(0.08), fixed(0.9), emb);
  fixed sp = fixed(0.0);
  for (int i = 0; i < 8; i = i + 1) {
    fixed d = abs(fixed(led.s) - sparks[i]);
    if (d < fixed(0.0625)) {
      fixed f = fixed(1.0) - d * fixed(16.0);
      sp = max(sp, f);
    }
  }
  vec3 spark_col = hsv2rgb(fixed(0.12), fixed(1.0), sp);
  return mix(c, spark_col, sp);
}

